// src/components/RoleSelection.js
import React from "react";
import { useNavigate } from "react-router-dom";
import "../index.css";

const RoleSelection = () => {
  const navigate = useNavigate();

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Select Your Role</h2>
        <p>Please choose how you want to use SoftScale.</p>

        <div className="role-buttons">
          <button
            className="btn-primary"
            onClick={() => navigate("/freelancer-form")}
          >
            Continue as Freelancer
          </button>
          <button
            className="btn-primary"
            onClick={() => navigate("/jobseeker-form")}
          >
            Continue as Job Seeker / Company
          </button>
        </div>
      </div>
    </div>
  );
};

export default RoleSelection;
